#### 🔄 有限状态机模式 (FSM)
**适用场景：**
- 协议解析（UART/I2C/SPI状态转换）
- 设备控制（开关机流程、工作模式切换）
- 用户界面（菜单导航、输入状态）
**实现结构：**
```c
// 状态机框架
typedef enum {
    STATE_IDLE,
    STATE_INIT,
    STATE_RUNNING,
    STATE_ERROR,
    STATE_SHUTDOWN
} SystemState;
typedef struct {
    SystemState current;
    SystemState (*handler[STATE_MAX])(Event e);
    void (*entry[STATE_MAX])(void);
    void (*exit[STATE_MAX])(void);
} StateMachine;
// 状态转换
SystemState fsm_handle_event(StateMachine* fsm, Event e) {
    if (fsm->handler[fsm->current]) {
        SystemState next = fsm->handler[fsm->current](e);
        if (next != fsm->current) {
            if (fsm->exit[fsm->current]) fsm->exit[fsm->current]();
            fsm->current = next;
            if (fsm->entry[fsm->current]) fsm->entry[fsm->current]();
        }
        return next;
    }
    return fsm->current;
}
```
**关键原则：**
- 每个状态独立处理函数
- 状态转换表驱动（可配置、可测试）
- 入口/出口动作分离
- 避免深层嵌套状态（≤3层）
#### 🏗️ 分层架构模式 (Layered Architecture)
```
┌────────────────────────────────────────┐
│           应用层 (Application)          │  业务逻辑、算法
├────────────────────────────────────────┤
│           服务层 (Service)              │  功能模块、协议栈
├────────────────────────────────────────┤
│           抽象层 (HAL)                  │  硬件抽象接口
├────────────────────────────────────────┤
│           驱动层 (Driver)               │  寄存器操作、中断
├────────────────────────────────────────┤
│           硬件层 (Hardware)             │  MCU、外设
└────────────────────────────────────────┘
```
**HAL设计原则：**
```c
// HAL接口定义（与硬件无关）
typedef struct {
    int (*init)(void);
    int (*read)(void* buf, size_t len);
    int (*write)(const void* buf, size_t len);
    int (*ioctl)(int cmd, void* arg);
    int (*close)(void);
} HAL_Device;
// 使用示例
HAL_Device* uart = HAL_GetDevice(HAL_UART0);
uart->init();
uart->write(data, len);
```

#### 💾 内存池模式 (Memory Pool)
```c
// 固定大小内存池
typedef struct {
    uint8_t* pool;
    size_t block_size;
    size_t block_count;
    uint8_t* free_list;
} MemPool;
void* pool_alloc(MemPool* mp) {
    if (mp->free_list == NULL) return NULL;
    void* block = mp->free_list;
    mp->free_list = *(uint8_t**)mp->free_list;
    return block;
}
void pool_free(MemPool* mp, void* block) {
    *(uint8_t**)block = mp->free_list;
    mp->free_list = block;
}
```
**优势：**
- 无内存碎片
- 分配/释放时间确定（O(1)）
- 适合实时系统
#### 🔁 环形缓冲模式 (Ring Buffer)
```c
typedef struct {
    uint8_t* buffer;
    size_t size;
    volatile size_t head;  // 写指针
    volatile size_t tail;  // 读指针
} RingBuffer;
// 无锁写入（单生产者）
void ring_write(RingBuffer* rb, uint8_t data) {
    size_t next = (rb->head + 1) % rb->size;
    if (next != rb->tail) {  // 非满
        rb->buffer[rb->head] = data;
        rb->head = next;
    }
}
// 无锁读取（单消费者）
bool ring_read(RingBuffer* rb, uint8_t* data) {
    if (rb->head == rb->tail) return false;  // 空
    *data = rb->buffer[rb->tail];
    rb->tail = (rb->tail + 1) % rb->size;
    return true;
}
```
**典型应用：**
- UART接收缓冲
- 数据采集缓存
- 日志缓冲

#### 🐕 看门狗模式 (Watchdog Pattern)
```c
// 多任务看门狗
typedef struct {
    uint32_t task_id;
    uint32_t timeout_ms;
    uint32_t last_kick;
    bool is_alive;
} TaskWatchdog;
void wdt_task_register(uint32_t task_id, uint32_t timeout);
void wdt_task_kick(uint32_t task_id);
void wdt_monitor_task(void);  // 低优先级监控任务
// 实现
void wdt_monitor_task(void) {
    while(1) {
        bool all_alive = true;
        for (int i = 0; i < task_count; i++) {
            if (!tasks[i].is_alive) all_alive = false;
            tasks[i].is_alive = false;  // 重置，等待下次kick
        }
        if (all_alive) {
            WDT_Kick();  // 只有所有任务都活着才喂狗
        }
        vTaskDelay(WDT_CHECK_INTERVAL);
    }
}
```
**设计原则：**
- 看门狗不是用来发现bug的，是最后一道防线
- 监控所有关键任务，不只是主循环
- 超时时间 > 最长任务执行时间 + 安全余量
- 喂狗时机要合理（任务完成关键操作后）
#### ❤️ 心跳检测模式 (Heartbeat)
```c
// 双机心跳
typedef struct {
    uint32_t local_tick;
    uint32_t remote_tick;
    uint32_t timeout_threshold;
    bool remote_alive;
} Heartbeat;
bool check_remote_alive(Heartbeat* hb) {
    uint32_t now = get_tick();
    if (now - hb->remote_tick > hb->timeout_threshold) {
        hb->remote_alive = false;
        trigger_failover();
    }
    return hb->remote_alive;
}
void send_heartbeat(Heartbeat* hb) {
    hb->local_tick = get_tick();
    send_message(MSG_HEARTBEAT, hb->local_tick);
}
```

**背景：** 某WiFi智能插座，频繁死机、响应慢
**问题设计：**
```c
// 问题1：前后台模式处理复杂逻辑
void main() {
    while(1) {
        wifi_process();      // 阻塞式WiFi处理
        button_scan();       // 按键扫描
        mqtt_process();       // MQTT处理
        relay_control();     // 继电器控制
        // 无优先级，WiFi阻塞导致按键响应慢
    }
}
// 问题2：动态内存分配
void process_message(char* msg) {
    char* buffer = malloc(1024);  // 堆碎片化
    parse(msg, buffer);
    free(buffer);
}
// 问题3：无看门狗设计
// 系统死锁后只能掉电重启
// 问题4：状态混乱
// 全局变量管理状态，多处修改，状态不一致
```
**后果：**
- 运行3-7天后死机（内存碎片）
- 按键响应延迟2-5秒
- OTA升级失败后变砖
- 用户投诉率 > 5%
**改进方案：**
- 引入RTOS，WiFi和继电器分离任务
- 固定大小内存池替代malloc
- 多任务看门狗 + 异常状态恢复
- 状态机重构，明确状态转换
